begin;
select plan(30);

select has_function('graftvision_private','save_model_landmark',array['uuid','uuid','uuid','text','numeric','numeric','numeric','text','integer','integer','uuid'],'typed landmark save exists');
select has_table('public','model_annotation_landmark_version','immutable landmark versions exist');
select has_table('public','model_annotation_landmark_current','authoritative landmark pointers exist');
select policies_are('public','model_annotation_landmark_version',array[]::name[],'ordinary landmark version access is denied');
select policies_are('public','model_annotation_landmark_current',array[]::name[],'ordinary landmark pointer access is denied');
select throws_ok($$insert into public.model_annotation_landmark_version(annotation_package_id,clinic_id,patient_id,consultation_id,model_package_id,reconstruction_output_manifest_id,model_artifact_id,geometry_revision,landmark_code,normalized_coordinate,coordinate_frame_version,revision,created_by) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),1,'glabella_reference',array[1::numeric,2::numeric,3::numeric],'graftvision-model-normalization-v1',1,gen_random_uuid())$$,null,null,'direct landmark-version mutation is blocked');
select throws_ok($$insert into public.model_annotation_landmark_current(annotation_package_id,clinic_id,patient_id,consultation_id,model_package_id,reconstruction_output_manifest_id,model_artifact_id,geometry_revision,normalization_version,landmark_code,current_version_id,updated_by) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),1,'graftvision-model-normalization-v1','glabella_reference',gen_random_uuid(),gen_random_uuid())$$,null,null,'direct current-pointer mutation is blocked');

select ok(position('require_scan_capture_context' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'first save derives trusted clinic context');
select ok(position('is_assigned_verified_doctor' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'assigned Doctor is required and Assistants are denied');
select ok(position('p.package_state<>''draft''' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'finalized or stale packages are denied');
select ok(position('p.reconstruction_output_manifest_id<>m.reconstruction_output_manifest_id' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'exact model output binding is required');
select ok(position('p.model_artifact_id<>m.reconstruction_artifact_id' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'exact model artifact binding is required');
select ok(position('p.geometry_revision<>m.geometry_revision' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'exact geometry binding is required');
select ok(position('glabella_reference' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'landmark catalogue is bounded');
select ok(position('NaN' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'NaN coordinates are rejected');
select ok(position('Infinity' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'infinite coordinates are rejected');
select ok(position('MODEL_LANDMARK_INVALID' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'malformed coordinates and codes are rejected');
select ok(position('for update' in lower(pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure)))>0,'package and pointer updates use row locking');
select ok(position('MODEL_LANDMARK_POINTER_CONFLICT' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'stale pointer revisions are rejected');
select ok(position('p.revision<>p_expected_package_revision' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'stale package revisions are rejected');
select ok(position('MODEL_LANDMARK_IDEMPOTENCY_MISMATCH' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'changed-payload replays are rejected');
select ok(position('model_annotation_landmark_version' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'each save appends an immutable landmark version');
select ok(position('prior_version_id=model_annotation_landmark_current.current_version_id' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'second save preserves the prior pointer');
select ok(position('revision=model_annotation_landmark_current.revision+1' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'pointer revision increments once');
select ok(position('update public.model_annotation_package set revision=revision+1' in lower(pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure)))>0,'package revision increments once');
select ok(position('model.landmark_saved' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'approved audit action is emitted');
select ok(position('annotation_package_id' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'audit metadata contains opaque annotation scope');
select ok(position('normalized_coordinate' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))>0,'coordinates remain only in the immutable version row');
select ok(position('storage_key' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))=0,'audit path excludes storage paths');
select ok(position('patient_name' in pg_get_functiondef('graftvision_private.save_model_landmark(uuid,uuid,uuid,text,numeric,numeric,numeric,text,integer,integer,uuid)'::regprocedure))=0,'audit path excludes patient identity');
select * from finish(); rollback;
